Given an array arr of non-negative integers and an integer target, the task is to count all subsets of the array whose sum is equal to the given target.Examples: Input: arr[] = [5, 2, 3, 10, 6, 8], target = 10Output: 3Explanation: The subsets {5, 2, 3}, {2, 8}, and {10} sum up to the target 10.Input: arr[] = [2, 5, 1, 4, 3], target = 10Output: 3Explanation: The subsets {2, 1, 4, 3}, {5, 1, 4}, and {2, 5, 3} sum up to the target 10.Input: arr[] = [5, 7, 8], target = 3Output: 0Explanation: There are no subsets of the array that sum up to the target 3.Input: arr[] = [35, 2, 8, 22], target = 0Output: 1Explanation: The empty subset is the only subset with a sum of 0.Try It YourselfTable of ContentUsing Recursion - O(2 ^ n) Time and O(n) SpaceUsing Top-Down Dp (memoization) - O(n * target) Time and O(n * target) SpaceUsing Dynamic Programming (Tabulation) - O(n * target) Time and O(n * target) SpaceUsing Space Optimised DP - O(n * target) Time and O(target) SpaceUsing Recursion - O(2 ^ n) Time and O(n) SpaceA recursive approach is to consider wo cases for each element in the array:Exclude the current element: The element at index i is not included in the subset, and the current sum remains unchanged. This leads to the recursion call countSubsets(i + 1, currentSum, target).Include the current element: The element at index i is included in the subset, and the sum is updated as currentSum + arr[i]. This leads to the recursion call countSubsets(i + 1, currentSum + arr[i], target).
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Recursive function to count subsets with the given sum
int countSubsets(int i, int currentSum, int target, vector<int> &arr)
{
    int n = arr.size();

    // If all elements have been processed,
    // check whether the current subset sum equals the target
    if (i == n)
    {
        return (currentSum == target);
    }

    // Exclude the current element
    int exclude = countSubsets(i + 1, currentSum, target, arr);

    // Include the current element if the sum
    // does not exceed the target
    int include = 0;
    if (currentSum + arr[i] <= target)
    {
        include = countSubsets(i + 1, currentSum + arr[i], target, arr);
    }

    // Return the total count of valid subsets
    return include + exclude;
}

// Function to count subsets with sum equal to target
int perfectSum(vector<int> &arr, int target)
{
    // Start recursion from index 0
    // with an initial sum of 0
    return countSubsets(0, 0, target, arr);
}

int main()
{
    vector<int> arr = {35, 2, 8, 22};
    int target = 0;

    cout << perfectSum(arr, target);

    return 0;
}


